  // proxies: [domain, [machines in initial order]]
  // ops: [kind, domain, arg] where kind is REQ, DOWN or UP;
  //      arg is the path for REQ and the machine id (as text) for DOWN / UP.
  // Return, for each machine 0..machineCount-1, the array of paths it received in order.
  // Write your solution here
  return Array.from({ length: machineCount }, () => [])
}

const t = input.split(/\s+/).filter(Boolean)
let pos = 0
const p = parseInt(t[pos++])
const m = parseInt(t[pos++])
const proxies = []
for (let i = 0; i < p; i++) {
  const d = t[pos++]
  const k = parseInt(t[pos++])
  const ms = []
  for (let j = 0; j < k; j++) ms.push(parseInt(t[pos++]))
  proxies.push([d, ms])
}
const q = parseInt(t[pos++])
const ops = []
for (let i = 0; i < q; i++) {
  ops.push([t[pos], t[pos + 1], t[pos + 2]])
  pos += 3
}
const logs = simulate(m, proxies, ops)
console.log(logs.map(l => [l.length, ...l].join(' ')).join('\n'))

