import java.util.*;
import java.io.*;

public class Main {
    // proxies: each entry is {domain, machine ids as text...} in initial order
    // ops: each entry is {kind, domain, arg}; kind is REQ, DOWN or UP;
    //      arg is the path for REQ and the machine id (as text) for DOWN / UP.
    // Return, for each machine 0..machineCount-1, the paths it received in order.
    static List<List<String>> simulate(int machineCount, List<String[]> proxies, List<String[]> ops) {
        // Write your solution here
        List<List<String>> logs = new ArrayList<>();
        for (int i = 0; i < machineCount; i++) logs.add(new ArrayList<>());
        return logs;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int p = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        List<String[]> proxies = new ArrayList<>();
        for (int i = 0; i < p; i++) {
            String d = st.nextToken();
            int k = Integer.parseInt(st.nextToken());
            String[] e = new String[k + 1];
            e[0] = d;
            for (int j = 0; j < k; j++) e[j + 1] = st.nextToken();
            proxies.add(e);
        }
        int q = Integer.parseInt(st.nextToken());
        List<String[]> ops = new ArrayList<>();
        for (int i = 0; i < q; i++) ops.add(new String[]{st.nextToken(), st.nextToken(), st.nextToken()});
        List<List<String>> logs = simulate(m, proxies, ops);
        StringBuilder sb = new StringBuilder();
        for (List<String> l : logs) {
            sb.append(l.size());
            for (String s : l) sb.append(' ').append(s);
            sb.append("\n");
        }
        System.out.print(sb);
    }
}
